-- Офіційні доступні кольори Papa Carlo Plato.
begin;
delete from public.product_specs
where label = 'Доступні декори' and product_slug in (
  select slug from public.products where brand = 'Papa Carlo' and collection = 'Plato'
);
;
commit;
select count(*) as моделей_з_кольорами from public.product_specs
where label = 'Доступні декори' and product_slug in (
  select slug from public.products where brand = 'Papa Carlo' and collection = 'Plato'
);
